/// Decodes the second byte of a `0xFE`-escaped opcode.
pub(crate) const fn decode_two(byte: u8) -> Option<OpCode> {
    match byte {
        0x00 => Some(OpCode::Arglist),
        0x01 => Some(OpCode::Ceq),
        0x02 => Some(OpCode::Cgt),
        0x03 => Some(OpCode::CgtUn),
        0x04 => Some(OpCode::Clt),
        0x05 => Some(OpCode::CltUn),
        0x06 => Some(OpCode::Ldftn),
        0x07 => Some(OpCode::Ldvirtftn),
        0x09 => Some(OpCode::Ldarg),
        0x0A => Some(OpCode::Ldarga),
        0x0B => Some(OpCode::Starg),
        0x0C => Some(OpCode::Ldloc),
        0x0D => Some(OpCode::Ldloca),
        0x0E => Some(OpCode::Stloc),
        0x0F => Some(OpCode::Localloc),
        0x11 => Some(OpCode::Endfilter),
        0x12 => Some(OpCode::Unaligned),
        0x13 => Some(OpCode::Volatile),
        0x14 => Some(OpCode::Tail),
        0x15 => Some(OpCode::Initobj),
        0x16 => Some(OpCode::Constrained),
        0x17 => Some(OpCode::Cpblk),
        0x18 => Some(OpCode::Initblk),
        0x19 => Some(OpCode::No),
        0x1A => Some(OpCode::Rethrow),
        0x1C => Some(OpCode::Sizeof),
        0x1D => Some(OpCode::Refanytype),
        0x1E => Some(OpCode::Readonly),
        _ => None,
    }
}

/// Maps a short or macro encoding to its general-purpose equivalent.
pub(crate) const fn canonical_of(op: OpCode) -> OpCode {
    match op {
        OpCode::Ldarg0 => OpCode::Ldarg,
        OpCode::Ldarg1 => OpCode::Ldarg,
        OpCode::Ldarg2 => OpCode::Ldarg,
        OpCode::Ldarg3 => OpCode::Ldarg,
        OpCode::Ldloc0 => OpCode::Ldloc,
        OpCode::Ldloc1 => OpCode::Ldloc,
        OpCode::Ldloc2 => OpCode::Ldloc,
        OpCode::Ldloc3 => OpCode::Ldloc,
        OpCode::Stloc0 => OpCode::Stloc,
        OpCode::Stloc1 => OpCode::Stloc,
        OpCode::Stloc2 => OpCode::Stloc,
        OpCode::Stloc3 => OpCode::Stloc,
        OpCode::LdargS => OpCode::Ldarg,
        OpCode::LdargaS => OpCode::Ldarga,
        OpCode::StargS => OpCode::Starg,
        OpCode::LdlocS => OpCode::Ldloc,
        OpCode::LdlocaS => OpCode::Ldloca,
        OpCode::StlocS => OpCode::Stloc,
        OpCode::LdcI4M1 => OpCode::LdcI4,
        OpCode::LdcI40 => OpCode::LdcI4,
        OpCode::LdcI41 => OpCode::LdcI4,
        OpCode::LdcI42 => OpCode::LdcI4,
        OpCode::LdcI43 => OpCode::LdcI4,
        OpCode::LdcI44 => OpCode::LdcI4,
        OpCode::LdcI45 => OpCode::LdcI4,
        OpCode::LdcI46 => OpCode::LdcI4,
        OpCode::LdcI47 => OpCode::LdcI4,
        OpCode::LdcI48 => OpCode::LdcI4,
        OpCode::LdcI4S => OpCode::LdcI4,
        OpCode::BrS => OpCode::Br,
        OpCode::BrfalseS => OpCode::Brfalse,
        OpCode::BrtrueS => OpCode::Brtrue,
        OpCode::BeqS => OpCode::Beq,
        OpCode::BgeS => OpCode::Bge,
        OpCode::BgtS => OpCode::Bgt,
        OpCode::BleS => OpCode::Ble,
        OpCode::BltS => OpCode::Blt,
        OpCode::BneUnS => OpCode::BneUn,
        OpCode::BgeUnS => OpCode::BgeUn,
        OpCode::BgtUnS => OpCode::BgtUn,
        OpCode::BleUnS => OpCode::BleUn,
        OpCode::BltUnS => OpCode::BltUn,
        OpCode::LeaveS => OpCode::Leave,
        other => other,
    }
}

/// The local or argument index a macro encoding implies.
pub(crate) const fn implied_var(op: OpCode) -> Option<u16> {
    match op {
        OpCode::Ldarg0 => Some(0),
        OpCode::Ldarg1 => Some(1),
        OpCode::Ldarg2 => Some(2),
        OpCode::Ldarg3 => Some(3),
        OpCode::Ldloc0 => Some(0),
        OpCode::Ldloc1 => Some(1),
        OpCode::Ldloc2 => Some(2),
        OpCode::Ldloc3 => Some(3),
        OpCode::Stloc0 => Some(0),
        OpCode::Stloc1 => Some(1),
        OpCode::Stloc2 => Some(2),
        OpCode::Stloc3 => Some(3),
        _ => None,
    }
}

/// The constant an `ldc.i4.*` macro encoding implies.
pub(crate) const fn implied_i32(op: OpCode) -> Option<i32> {
    match op {
        OpCode::LdcI4M1 => Some(-1),
        OpCode::LdcI40 => Some(0),
        OpCode::LdcI41 => Some(1),
        OpCode::LdcI42 => Some(2),
        OpCode::LdcI43 => Some(3),
        OpCode::LdcI44 => Some(4),
        OpCode::LdcI45 => Some(5),
        OpCode::LdcI46 => Some(6),
        OpCode::LdcI47 => Some(7),
        OpCode::LdcI48 => Some(8),
        _ => None,
    }
}
